// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {AirDropContract} from "../src/AirDropContract.sol";

contract InvMutTest is Test {
    AirDropContract c;
    function setUp() public { c = new AirDropContract(); }

    function testFuzz_property(address callee, uint256 v) public {
        vm.assume(v > 0);

        Reverter r = new Reverter();

        address target = callee;
        if (target == address(0)) {
        } else {
            target = address(r);
        }

        address[] memory tos = new address[](1);
        tos[0] = address(this);
        uint[] memory vs = new uint[](1);
        vs[0] = v;

        bool ok;
        try c.transfer(target, tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter { fallback() external payable { revert(); } }
